			SELECT count(*) INTO _count FROM users 
				WHERE username = _uname AND password = _password;
			IF _count > 0 THEN
				SELECT 0 error, 'success' msg, _uname as `username`;
			ELSE 
				SELECT 3 error, 'Incorrect password' msg;
			END IF;
